    uint8 errorCode = DCM_E_OK;
    uint8 retVal = DCM_E_OK;
    uint16 dtc_Number = DCM_ZERO;

    retValDem = (uint8)Dem_DcmGetNumberOfFilteredDTC(&dtc_Number);  /* Get dtc number. */

