                        Dcm_RepeatedProxyContexts.Dcm_09_ProxyContext.Dcm_PidNum++;
                        Dcm_RepeatedProxyContexts.Dcm_09_ProxyContext.Dcm_TypeInfo = (uint8)DCM_09_SUPPORT_PIDSET;
                        exitFlg = TRUE;
