                        actDelayTime
                            = Dcm_27_SetDelayTime(Dcm_27_Dispatcher.Dcm_ServiceInfoTable[Dcm_SeedKeyProxyParam.Dcm_SecLevIdxOnGotSeed].Dcm_DelayInvKey);
                        Dcm_27_TmrMgrStartTimer(Dcm_SeedKeyProxyParam.Dcm_SecLevIdxOnGotSeed, actDelayTime);
