    if( DCM_MAINTASK_CYCLE >= delayTime )
    /* Polyspace +1 RTE:UNR [JUstified:Unset] "NSCA_Polyspace_Common_Unreachable" */
    {
        actDelayTime = DCM_ONE;
    }
