    /* Polyspace +1 MISRA-C3:D4.5 [Justified:Unset] "NSCA_Polyspace_Dcm_Dir4.5" */
    uint16 did;
    uint32 didIndex;

    /* Polyspace +1 MISRA-C3:D4.1 [Justified:Unset] "NSCA_Polyspace_Dcm_PtrOutside"  Polyspace +1 MISRA-C3:18.1 [Justified:Unset] "NSCA_Polyspace_Dcm_PtrOutside"  Polyspace +1 RTE:IDP [JUstified:Unset] "NSCA_Polyspace_Dcm_IDP"  Polyspace +1 RTE:NIV [JUstified:Unset] "NSCA_Polyspace_Dcm_NIV" */
