                Dcm_DsdMsgContext.Dcm_ResData[DCM_OFFSET_TWO] = Dcm_GetLoHiByte(dtcVal);
                /* Polyspace +1 MISRA-C3:D4.1 [Justified:Unset] "NSCA_Polyspace_Dcm_PtrOutside"  Polyspace +1 MISRA-C3:18.1 [Justified:Unset] "NSCA_Polyspace_Dcm_PtrOutside"  Polyspace +1 RTE:IDP [JUstified:Unset] "NSCA_Polyspace_Dcm_IDP" */
                Dcm_DsdMsgContext.Dcm_ResData[DCM_OFFSET_THREE] = Dcm_GetLoLoByte(dtcVal);
                /* Polyspace +1 MISRA-C3:D4.1 [Justified:Unset] "NSCA_Polyspace_Dcm_PtrOutside"  Polyspace +1 MISRA-C3:18.1 [Justified:Unset] "NSCA_Polyspace_Dcm_PtrOutside"  Polyspace +1 RTE:IDP [JUstified:Unset] "NSCA_Polyspace_Dcm_IDP" */
                Dcm_DsdMsgContext.Dcm_ResData[DCM_OFFSET_FOUR] = dtcStatus;
