            (void)Dcm_CheckServiceState(&Dcm_2A_Dispatcher.Dcm_ServiceInfoTable[Dcm_2A_SchdTable[schdCnt].Dcm_DidHandle].Dcm_ReadFilter,
                                            DCM_STATE_LVL_PARAM, &errorCode);
            if( DCM_E_OK == errorCode )
            {
                (void)Dcm_CheckAuthServiceState(&Dcm_2A_Dispatcher.Dcm_ServiceInfoTable[Dcm_2A_SchdTable[schdCnt].Dcm_DidHandle].Dcm_AutFilter, &errorCode);
            }
