        Dcm_86_InfoData_DefaultSession[eventIdx].Dcm_EventWndTime = DCM_ROE_EVENT_WINDOW_CURRENT_CYCLE;
        Dcm_86_InfoData_DefaultSession[eventIdx].Dcm_StorageStatus = FALSE;

