                /* Polyspace +1 MISRA-C3:2.1 [Justified:Unset] "NSCA_Polyspace_Common_Unreachable" */
                Dcm_86_NvMInfo.NvmInfo.NvMInfoData.Dcm_InfoData[eventIndex].Dcm_EventMask = DCM_ZERO;
                /* Polyspace +1 MISRA-C3:2.1 [Justified:Unset] "NSCA_Polyspace_Common_Unreachable" */
                Dcm_86_NvMInfo.NvmInfo.NvMInfoData.Dcm_InfoData[eventIndex].Dcm_StorageStatus = FALSE;
                /* Polyspace +1 MISRA-C3:2.1 [Justified:Unset] "NSCA_Polyspace_Common_Unreachable" */
                Dcm_86_NvMInfo.NvmInfo.NvMInfoData.Dcm_InfoData[eventIndex].Dcm_EventWndTime = DCM_ROE_EVENT_WINDOW_CURRENT_CYCLE;
                /* Polyspace +1 MISRA-C3:2.1 [Justified:Unset] "NSCA_Polyspace_Common_Unreachable" */
