            roeDslInfo->TxPduId = DCM_ZERO;
            Dcm_86_NvMInfo.NvmInfo.NvMInfoData.Dcm_DslInfo.RxPduId = DCM_ZERO;
            Dcm_86_NvMInfo.NvmInfo.NvMInfoData.Dcm_DslInfo.TxPduId = DCM_ZERO;
            Dcm_86_NvMInfo.NvmInfo.NvMInfoData.Dcm_DslInfo.ClientSrcAddr = DCM_ZERO;
